<?php
require_once 'common.php'; require_customer();
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(isset($_POST['remove_id'])) unset($_SESSION['cart'][(int)$_POST['remove_id']]);
    if(isset($_POST['update_cart'])) foreach(($_POST['qty']??[]) as $id=>$qty){$id=(int)$id;$qty=max(0,(int)$qty);$st=$conn->prepare('SELECT stock FROM products WHERE product_id=?');$st->bind_param('i',$id);$st->execute();$r=$st->get_result()->fetch_assoc();if(!$r||$qty===0)unset($_SESSION['cart'][$id]);else $_SESSION['cart'][$id]=min($qty,(int)$r['stock']);}
    header('Location: cart.php');exit();
}
$items=[];$total=0;$cart=$_SESSION['cart']??[];
if($cart){$ids=array_keys($cart);$place=implode(',',array_fill(0,count($ids),'?'));$types=str_repeat('i',count($ids));$stmt=$conn->prepare("SELECT product_id,product_name,category,price,stock FROM products WHERE product_id IN ($place)");$stmt->bind_param($types,...$ids);$stmt->execute();$r=$stmt->get_result();while($p=$r->fetch_assoc()){$q=(int)($cart[$p['product_id']]??0);$sub=$q*$p['price'];$p['quantity']=$q;$p['subtotal']=$sub;$items[]=$p;$total+=$sub;}}
$shop_title='Shopping Cart';include 'header.php';
?>
<div class="section-head"><div><h2>Your Cart</h2><p>Review quantities before checkout.</p></div><a class="btn btn-outline" href="products.php"><i class="fa-solid fa-arrow-left"></i> Continue Shopping</a></div>
<?php if(!$items): ?><div class="card-panel" style="padding:55px;text-align:center"><i class="fa-solid fa-cart-shopping" style="font-size:42px;color:#c87932"></i><h3>Your cart is empty</h3><p style="color:var(--muted)">Add products from the store to start an order.</p><a class="btn btn-dark" href="products.php">Browse Products</a></div><?php else: ?>
<form method="post"><div class="cart-layout"><div class="card-panel"><div class="panel-head"><h2>Cart Items</h2><span style="font-size:12px;color:var(--muted)"><?php echo cart_count(); ?> item(s)</span></div><?php foreach($items as $item): ?><div class="cart-item"><div class="cart-product"><div class="mini-art"><i class="fa-solid fa-bread-slice"></i></div><div><strong><?php echo shop_e($item['product_name']); ?></strong><div style="font-size:11px;color:var(--muted)"><?php echo shop_e($item['category']); ?> · ₱<?php echo number_format($item['price'],2); ?> each</div></div></div><div class="qty"><input type="number" name="qty[<?php echo $item['product_id']; ?>]" min="0" max="<?php echo $item['stock']; ?>" value="<?php echo $item['quantity']; ?>"></div><strong>₱<?php echo number_format($item['subtotal'],2); ?></strong><button class="btn btn-outline" name="remove_id" value="<?php echo $item['product_id']; ?>" title="Remove"><i class="fa-solid fa-trash"></i></button></div><?php endforeach; ?><div style="padding:18px 22px;border-top:1px solid var(--line)"><button class="btn btn-outline" name="update_cart"><i class="fa-solid fa-rotate"></i> Update Cart</button></div></div><aside class="card-panel summary"><h2 style="font-size:17px;margin-top:0">Order Summary</h2><div class="summary-row"><span>Items</span><span><?php echo cart_count(); ?></span></div><div class="summary-row"><span>Subtotal</span><span>₱<?php echo number_format($total,2); ?></span></div><div class="summary-row"><span>Processing</span><span>₱0.00</span></div><div class="summary-row summary-total"><span>Total</span><span>₱<?php echo number_format($total,2); ?></span></div><a class="btn btn-dark" style="width:100%;margin-top:18px" href="checkout.php"><i class="fa-solid fa-credit-card"></i> Proceed to Checkout</a></aside></div></form>
<?php endif; ?>
<?php include 'footer.php'; ?>
